const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.whatsapp ?? [];
const santri = payload.santri ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};

function normalizePhone(phone) {
  const raw = String(phone ?? '').replace(/[^0-9]/g, '');
  if (raw.startsWith('08')) return '62' + raw.slice(1);
  if (raw.startsWith('8')) return '62' + raw;
  return raw;
}

function roleLabel(role) {
  if (role === 'ibu') return 'Ibu';
  if (role === 'wali') return 'Bapak/Ibu Wali';
  return 'Bapak';
}

function groupNoticeFor(recipient) {
  const isAkhwat = group.kelas === 'akhwat';
  if (!isAkhwat) return group.aturan ?? 'Untuk peserta didik putra, Bapak dan Ibu dipersilakan bergabung ke grup kelas ikhwan.';
  if (recipient.role === 'ibu') return group.aturan ?? 'Untuk peserta didik putri, link grup kelas akhwat dikirim khusus ke nomor WhatsApp Ibu. Hanya Ibu yang diperbolehkan bergabung ke group tersebut.';
  return 'Untuk peserta didik putri, link grup kelas akhwat dikirim khusus ke nomor WhatsApp Ibu. Hanya Ibu yang diperbolehkan bergabung ke group tersebut.';
}

function groupLinkTextFor(recipient) {
  const mayReceiveGroupLink = group.kelas !== 'akhwat' || recipient.role === 'ibu';
  const groupUrl = recipient.group_join_url || (mayReceiveGroupLink ? group.link : '');
  if (groupUrl) {
    return 'Link grup: ' + groupUrl + '\n\nSilakan buka link di atas untuk bergabung ke grup. Link ini khusus untuk ' + roleLabel(recipient.role) + '.';
  }
  if (!mayReceiveGroupLink) return '';
  return 'Link grup belum tersedia. Admin akan mengirimkan link menyusul.';
}

const summaryText = Object.entries(ringkasan)
  .map(([label, value]) => '- ' + label + ': ' + (value ?? '-'))
  .join('\n');

return recipients.map((recipient) => {
  const kelasLabel = group.kelas === 'ikhwan' ? 'ikhwan (putra)' : 'akhwat (putri)';
  const greeting = (roleLabel(recipient.role) + ' ' + (recipient.name ?? '')).trim();
  const groupLinkText = groupLinkTextFor(recipient);
  const message = 'Assalamu\'alaikum ' + greeting + ',\n\n' +
    'Alhamdulillah, data pendataan SPSB untuk ananda *' + (santri.nama_lengkap ?? '-') + '* sudah masuk dan diterima oleh sistem.\n\n' +
    '*Ringkasan data:*\n' + summaryText + '\n\n' +
    '*Informasi grup kelas ' + kelasLabel + ':*\n' + groupNoticeFor(recipient) + (groupLinkText ? '\n' + groupLinkText : '') + '\n\n' +
    'Tautan lihat/cetak data pendataan. Tombol Download PDF tersedia di halaman tersebut:\n' + (payload.links?.cetak ?? '-') + '\n\n' +
    'Jazakumullah khairan.\nPanitia SPSB';

  return {
    json: {
      phone: normalizePhone(recipient.phone),
      role: recipient.role,
      name: recipient.name,
      event: 'pendataan_baru',
      message,
      payload
    }
  };
});
